<?php require '_init.php';$title='Commandes';$statuses=['pending','confirmed','processing','shipped','delivered','cancelled'];if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$st=$_POST['status']??'';if(in_array($st,$statuses,true))$pdo->prepare("UPDATE orders SET status=? WHERE id=?")->execute([$st,(int)$_POST['id']]);flash('Commande mise à jour.');go('orders.php');}$orders=$pdo->query("SELECT * FROM orders ORDER BY created_at DESC")->fetchAll();require '../includes/header.php';?><section class="banner"><div class="container"><h1>COMMANDES</h1></div></section><section class="container section"><div class="adminnav"><a href="dashboard.php">Dashboard</a><a href="products.php">Produits</a><a href="categories.php">Catégories</a><a href="orders.php">Commandes</a><a href="users.php">Utilisateurs</a></div><div class="tablewrap"><table><tr><th>Référence</th><th>Client</th><th>Total</th><th>Statut</th><th>Modifier</th></tr><?php foreach($orders as $o):?><tr><td><?=e($o['order_number'])?></td><td><?=e($o['customer_name'])?></td><td><?=money($o['total'])?></td><td><?=e($o['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=(int)$o['id']?>"><select name="status"><?php foreach($statuses as $st):?><option <?=($o['status']===$st?'selected':'')?> value="<?=e($st)?>"><?=e($st)?></option><?php endforeach?></select><button class="btn mini">OK</button></form></td></tr><?php endforeach?></table></div></section><?php require '../includes/footer.php';?>
